//! All 83 upstream libavoid test fixtures
//! (`vendor/adaptagrams/cola/libavoid/tests/*.cpp`), executed from the op
//! scripts in `tests/fixtures/*.ops` (generated by
//! `tools/fixtures/convert.py`; interpreter in `tests/common/fixture_ops.rs`)
//! and compared with the goldens the real C++ produced (`tests/golden/`).
//!
//! The list below is the single source of truth for fixture status:
//!
//! * `golden NAME;` -- must reproduce every `outputDiagram()` dump, the
//!   final router state, the exit code and (if the fixture prints) stdout.
//! * `#[ignore = "blocked: ..."]` -- currently hits a `todo!()` in a module
//!   that is not ported yet.  `cargo test --test fixtures_ops -- --ignored`
//!   (or `tools/fixtures/run_all.sh`) shows what remains.  Remove the
//!   attribute when the fixture passes.
//! * `slow NAME;` -- upstream took up to minutes; the test returns
//!   immediately unless `LIBAVOID_SLOW_FIXTURES=1` is set (run in release:
//!   `LIBAVOID_SLOW_FIXTURES=1 cargo test --release --test fixtures_ops -- --include-ignored NAME`).
//! * `smoke NAME;` -- the fixture does not compile against the current
//!   upstream API (see the `.ops` header for the modernisations applied), so
//!   there is no golden: the scene is only run, nothing is compared.
//!
//! `2junctions` is not a valid Rust identifier; its test is `_2junctions`.

#![allow(non_snake_case)]
#![allow(clippy::uninlined_format_args)]

mod common;
#[path = "common/fixture_ops.rs"]
mod fixture_ops;

/// Environment variable enabling the slow fixtures.
const SLOW_ENV: &str = "LIBAVOID_SLOW_FIXTURES";

fn run(kind: &str, name: &str) {
    match kind {
        "golden" => {
            let r = fixture_ops::run_fixture(name);
            assert!(r.golden_mode, "{}.ops is not a golden-mode script", name);
        }
        "slow" => {
            if std::env::var_os(SLOW_ENV).is_none_or(|v| v.is_empty() || v == "0") {
                eprintln!("skipping slow fixture {} (set {}=1 to run it)", name, SLOW_ENV);
                return;
            }
            let r = fixture_ops::run_fixture(name);
            if !r.golden_mode {
                eprintln!("smoke fixture {}: main() returned {} (not compared)", name, r.exit_code);
            }
        }
        "smoke" => {
            let r = fixture_ops::run_fixture(name);
            assert!(!r.golden_mode, "{}.ops is not a smoke-mode script", name);
            eprintln!("smoke fixture {}: main() returned {} (not compared: no upstream golden)", name, r.exit_code);
        }
        _ => unreachable!(),
    }
}

macro_rules! fixtures {
    ($( $(#[$m:meta])* $kind:ident $test:ident $(= $file:literal)? ; )*) => {
        $(
            $(#[$m])*
            #[test]
            fn $test() {
                run(stringify!($kind), fixtures!(@file $test $($file)?));
            }
        )*
    };
    (@file $test:ident $file:literal) => { $file };
    (@file $test:ident) => { stringify!($test) };
}

