/// Interpreter self-test (not a fixture): runs every op script to the end
/// with the router forced to poly-line routing, so that all ops after the
/// first `processTransaction` are exercised against the real API even while
/// the orthogonal router is unported.  Fails only on interpreter errors
/// (`fixture-ops interpreter:` panics); library panics are reported.
#[test]
#[ignore = "interpreter self-test; run with --ignored interpreter_dry_run (release recommended)"]
fn interpreter_dry_run() {
    let dir = format!("{}/tests/fixtures", env!("CARGO_MANIFEST_DIR"));
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| e.ok()?.file_name().into_string().ok()?.strip_suffix(".ops").map(String::from))
        .collect();
    names.sort();
    let mut interp_errors = Vec::new();
    for name in &names {
        if ["performance01", "slowrouting", "reallyslowrouting", "unsatisfiableRangeAssertion"].contains(&name.as_str())
            && std::env::var_os(SLOW_ENV).is_none()
        {
            eprintln!("dry run {}: skipped (slow; set {}=1)", name, SLOW_ENV);
            continue;
        }
        let r = std::panic::catch_unwind(|| fixture_ops::dry_run_fixture(name));
        match r {
            Ok(r) => eprintln!("dry run {}: ok (main() returned {})", name, r.exit_code),
            Err(p) => {
                let msg = p
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| p.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default();
                eprintln!("dry run {}: PANIC {}", name, msg);
                if msg.contains("fixture-ops interpreter:") {
                    interp_errors.push(format!("{}: {}", name, msg));
                }
            }
        }
    }
    assert!(interp_errors.is_empty(), "interpreter errors:\n{}", interp_errors.join("\n"));
}
